package com.yuegang.zhihui.user.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.user.security.*;import jakarta.servlet.http.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/organization")public final class InternalOrganizationTargetController{private final JdbcTemplate jdbc;private final UserInternalServiceVerifier verifier;public InternalOrganizationTargetController(DataSource d,UserInternalServiceVerifier v){jdbc=new JdbcTemplate(d);verifier=v;}@GetMapping("/targets")ApiResponse<List<String>>targets(@RequestParam String type,@RequestParam String id,HttpServletRequest r){verifier.verify(r);long target=positive(id);List<String>users=switch(type){case"DEPARTMENT"->jdbc.queryForList("SELECT CAST(user_id AS CHAR) FROM user_employee WHERE department_id=? AND employment_status='ACTIVE'",String.class,target);case"POSITION"->jdbc.queryForList("SELECT CAST(e.user_id AS CHAR) FROM user_employee e JOIN user_employee_position ep ON ep.employee_id=e.id WHERE ep.position_id=? AND e.employment_status='ACTIVE'",String.class,target);case"EMPLOYEE"->jdbc.queryForList("SELECT CAST(user_id AS CHAR) FROM user_employee WHERE id=? AND employment_status='ACTIVE'",String.class,target);default->throw new BusinessException(ErrorCode.VALIDATION_ERROR);};return ApiResponse.success(users,TraceIdResolver.resolve(r));}private static long positive(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
